		receptive_field_center_start = { 3, 3, 7, 7, 15, 31, 31, 31 };

		for (size_t i = 0; i < receptive_field_list.size(); i++) {
			constant.push_back(receptive_field_list[i] / 2);
		}

		output_blob_names={ "softmax0","conv8_3_bbox",
