bool pentagonal_get(int num,vector<int> &vect)
{
    int fx_i;
    if (num<=0 || num>1024)
    {
        return false;
    }
    else
    {
        for (int i = 1; i <= num; i++)
        {
            fx_i = i*(i*3-1)/2;
            vect.push_back(fx_i);
        }
    }
    return true;
}

