{
    vector<int> vect;

    bool res;
    int num;
    cout<<"please enter num"<<endl<<endl;

    while (cin>>num)
    {
        res = pentagonal_get(num,vect);

        if (res == false)
        {
            cout<<"overflow"<<endl;
        }
        else
        {
            vect_printf(vect,"int");
        }
        vector<int>().swap(vect);
    }

    return 0;
}

