		return VK_FORMAT_R32G32_SINT;
	case api::format::r32g32_typeless:
	case api::format::r32g32_float:
		return VK_FORMAT_R32G32_SFLOAT;
	case api::format::r32g32b32_uint:
		return VK_FORMAT_R32G32B32_UINT;
