std::string CLink::LinkState() const
{
    if (nLinkState == 0) {
        return "Unknown";
    }
    else if (nLinkState == 1) {
        return "Pending";
    }
    else if (nLinkState == 2) {
        return "Complete";
    }
    else if (nLinkState == 3) {
        return "Deleted";
    }
    return "Undefined";
}

