            FC_ASSERT(is_open());
            FC_ASSERT(is_unlocked());
            const auto current_account = my->_wallet_db.lookup_account(account_name);
            
            if (!current_account.valid())
                FC_THROW_EXCEPTION(invalid_name, "No account with this name in wallet!");
                
