    ShuffleIterator it(&rd, 1231212);
    ASSERT_TRUE(it.initialize());
    EXPECT_EQ(3,it.size());
    ASSERT_TRUE(it.has_next());
    RecDat* recDat = it.next();
    EXPECT_EQ(3, recDat->item);
    ASSERT_TRUE(it.has_next());
