        // invocation is recorded.
    {
         // Compiler warnings suppression.

        (void)args_01;
        (void)args_02;

        g_calledMethodFlag |= e_EMPLACE_2;
        d_vector.push_back(value_type(1));
    }

    template <class Args_01,
              class Args_02,
              class Args_03>
