                        Flags<SizedEnum>(kSizedEnum_Two))
                  .IsEmpty(),
              "SizedEnum {Zero,One} intersect Two is not empty");
static_assert(Flags<SizedEnum>({kSizedEnum_One, kSizedEnum_Two}) ==
                  Flags<SizedEnum>(kSizedEnum_One, kSizedEnum_Two),
