int FindPunchLocation(int hitGroup)
{
    int roll = Number(1, 6);

    switch (hitGroup) {
    case LEFTSIDE:
    switch (roll) {
    case 1:
    case 2:
        return LTORSO;
    case 3:
        return CTORSO;
    case 4:
    case 5:
        return LARM;
    case 6:
        return HEAD;
    }
    case BACK:
    case FRONT:
    switch (roll) {
    case 1:
        return LARM;
    case 2:
        return LTORSO;
    case 3:
        return CTORSO;
    case 4:
        return RTORSO;
    case 5:
        return RARM;
    case 6:
        return HEAD;
    }
    break;

    case RIGHTSIDE:
    switch (roll) {
    case 1:
    case 2:
        return RTORSO;
    case 3:
        return CTORSO;
    case 4:
    case 5:
        return RARM;
    case 6:
        return HEAD;
    }
    }
    return CTORSO;
}

int FindKickLocation(int hitGroup)
{
    int roll = Number(1, 6);

    switch (hitGroup) {
    case LEFTSIDE:
    return LLEG;
    case BACK:
    case FRONT:
    switch (roll) {
    case 1:
    case 2:
    case 3:
        return RLEG;
    case 4:
    case 5:
    case 6:
        return LLEG;
    }
    case RIGHTSIDE:
    return RLEG;
    }
    return RLEG;
}

int get_bsuit_hitloc(MECH * mech)
{
    int i;
    int table[NUM_BSUIT_MEMBERS];
    int last = 0;

    for (i = 0; i < NUM_BSUIT_MEMBERS; i++)
    if (GetSectInt(mech, i))
        table[last++] = i;
    if (!last)
    return -1;
    return table[Number(0, last - 1)];
}

int TransferTarget(MECH * mech, int hitloc)
{
    switch (MechType(mech)) {
    case CLASS_BSUIT:
    return get_bsuit_hitloc(mech);
    case CLASS_AERO:
    switch (hitloc) {
    case AERO_NOSE:
    case AERO_LWING:
    case AERO_RWING:
    case AERO_ENGINE:
    case AERO_COCKPIT:
        return AERO_FUSEL;
    }
    break;
    case CLASS_MECH:
    case CLASS_MW:
    switch (hitloc) {
    case RARM:
    case RLEG:
        return RTORSO;
        break;
    case LARM:
    case LLEG:
        return LTORSO;
        break;
    case RTORSO:
    case LTORSO:
        return CTORSO;
        break;
    }
    break;
    }
    return -1;
}

int FindSwarmHitLocation(int *iscritical, int *isrear)
{
    *isrear = 0;
    *iscritical = 1;

    switch (Roll()) {
    case 12:
    case 2:
    return HEAD;
    case 3:
    case 11:
    *isrear = 1;
    return CTORSO;
    case 4:
    *isrear = 1;
    case 5:
    return RTORSO;
    case 10:
    *isrear = 1;
    case 9:
    return LTORSO;
    case 6:
    return RARM;
    case 8:
    return LARM;
    case 7:
    return CTORSO;
    }
    return HEAD;
}

int crittable(MECH * mech, int loc, int tres)
{
    int d;

    if (MechMove(mech) == MOVE_NONE)
    return 0;
    if (!GetSectOArmor(mech, loc))
    return 1;
    if (MechType(mech) != CLASS_MECH && btechconf.btech_vcrit <= 1)
    return 0;
    d = (100 * GetSectArmor(mech, loc)) / GetSectOArmor(mech, loc);
    if (d < tres)
    return 1;
    if (d == 100) {
    if (Number(1, 71) == 23)
        return 1;
    return 0;
    }
    if (d < (100 - ((100 - tres) / 2)))
    if (Number(1, 11) == 6)
        return 1;
    return 0;
}

int FindFasaHitLocation(MECH * mech, int hitGroup, int *iscritical,
    int *isrear)
{
    int roll, hitloc = 0;
    int side;

    *iscritical = 0;
    roll = Roll();

    if (MechStatus(mech) & COMBAT_SAFE)
    return 0;

    if (MechDugIn(mech) && GetSectOInt(mech, TURRET) &&
    Number(1, 100) >= 42)
    return TURRET;

    rollstat.hitrolls[roll - 2]++;
    rollstat.tothrolls++;
    switch (MechType(mech)) {
    case CLASS_BSUIT:
    if ((hitloc = get_bsuit_hitloc(mech)) < 0)
        return Number(0, NUM_BSUIT_MEMBERS - 1);
    case CLASS_MW:
    case CLASS_MECH:
    switch (hitGroup) {
    case LEFTSIDE:
        switch (roll) {
        case 2:
        *iscritical = 1;
        return LTORSO;
        case 3:
        return LLEG;
        case 4:
        case 5:
        return LARM;
        case 6:
        return LLEG;
        case 7:
        return LTORSO;
        case 8:
        return CTORSO;
        case 9:
        return RTORSO;
        case 10:
        return RARM;
        case 11:
        return RLEG;
        case 12:
        return HEAD;
        }
    case RIGHTSIDE:
        switch (roll) {
        case 2:
        *iscritical = 1;
        return RTORSO;
        case 3:
        return RLEG;
        case 4:
        case 5:
        return RARM;
        case 6:
        return RLEG;
        case 7:
        return RTORSO;
        case 8:
        return CTORSO;
        case 9:
        return LTORSO;
        case 10:
        return LARM;
        case 11:
        return LLEG;
        case 12:
        return HEAD;
        }
    case FRONT:
    case BACK:
        switch (roll) {
        case 2:
        *iscritical = 1;
        return CTORSO;
        case 3:
        case 4:
        return RARM;
        case 5:
        return RLEG;
        case 6:
        return RTORSO;
        case 7:
        return CTORSO;
        case 8:
        return LTORSO;
        case 9:
        return LLEG;
        case 10:
        case 11:
        return LARM;
        case 12:
        return HEAD;
        }
    }
    break;
    case CLASS_VEH_GROUND:
    switch (hitGroup) {

    case LEFTSIDE:
        switch (roll) {
        case 2:
        /* A Roll on Determining Critical Hits Table */
        *iscritical = 1;
        return LSIDE;
        case 3:
        if (btechconf.btech_tankfriendly) {
            if (!Fallen(mech)) {
            mech_notify(mech, MECHALL,
                "%ch%cyCRITICAL HIT!!%c");
            switch (MechMove(mech)) {
            case MOVE_TRACK:
                mech_notify(mech, MECHALL,
                "One of your tracks is seriously damaged!!");
                break;
            case MOVE_WHEEL:
                mech_notify(mech, MECHALL,
                "One of your wheels is seriously damaged!!");
                break;
            case MOVE_HOVER:
                mech_notify(mech, MECHALL,
                "Your air skirt is seriously damaged!!");
                break;
            case MOVE_HULL:
            case MOVE_SUB:
            case MOVE_FOIL:
                mech_notify(mech, MECHALL,
                "Your speed slows down a lot..");
                break;
            }
            LowerMaxSpeed(mech, MP2);
            }
            return LSIDE;
        }
        /* Cripple tank */
        if (!Fallen(mech)) {
            mech_notify(mech, MECHALL, "%ch%cyCRITICAL HIT!!%c");
            switch (MechMove(mech)) {
            case MOVE_TRACK:
            mech_notify(mech, MECHALL,
                "One of your tracks is destroyed, imobilizing your vehicle!!");
            break;
            case MOVE_WHEEL:
            mech_notify(mech, MECHALL,
                "One of your wheels is destroyed, imobilizing your vehicle!!");
            break;
            case MOVE_HOVER:
            mech_notify(mech, MECHALL,
                "Your lift fan is destroyed, imobilizing your vehicle!!");
            break;
            case MOVE_HULL:
            case MOVE_SUB:
            case MOVE_FOIL:
            mech_notify(mech, MECHALL,
                "You are halted in your tracks - literally.");
            }
            SetMaxSpeed(mech, 0.0);

            MakeMechFall(mech);
        }
        return LSIDE;
        case 4:
        case 5:
        /* MP -1 */
        if (!Fallen(mech)) {
            mech_notify(mech, MECHALL, "%ch%cyCRITICAL HIT!!%c");
            switch (MechMove(mech)) {
            case MOVE_TRACK:
            mech_notify(mech, MECHALL,
                "One of your tracks is damaged!!");
            break;
            case MOVE_WHEEL:
            mech_notify(mech, MECHALL,
                "One of your wheels is damaged!!");
            break;
            case MOVE_HOVER:
            mech_notify(mech, MECHALL,
                "Your air skirt is damaged!!");
            break;
            case MOVE_HULL:
            case MOVE_SUB:
            case MOVE_FOIL:
            mech_notify(mech, MECHALL,
                "Your speed slows down..");
            break;
            }
            LowerMaxSpeed(mech, MP1);
        }
        return LSIDE;
        break;
        case 6:
        case 7:
        case 8:
        case 9:
        /* MP -1 if hover */
        return LSIDE;
        case 10:
        return (GetSectInt(mech, TURRET)) ? TURRET : LSIDE;
        case 11:
        if (GetSectInt(mech, TURRET)) {
            if (!(MechTankCritStatus(mech) & TURRET_LOCKED)) {
            mech_notify(mech, MECHALL,
                "%ch%cyCRITICAL HIT!!%c");
            MechTankCritStatus(mech) |= TURRET_LOCKED;
            mech_notify(mech, MECHALL,
                "Your turret takes a direct hit and immobilizes!");
            }
            return TURRET;
        } else
            return LSIDE;
        case 12:
        /* A Roll on Determining Critical Hits Table */
        *iscritical = 1;
        return LSIDE;
        }
        break;
    case RIGHTSIDE:
        switch (roll) {
        case 2:
        *iscritical = 1;
        return RSIDE;
        case 3:
        if (btechconf.btech_tankfriendly) {
            if (!Fallen(mech)) {
            mech_notify(mech, MECHALL,
