/* Do L3 FASA motive system crits */
void DoMotiveSystemHit(MECH * mech, int wRollMod)
{
    int wRoll;
    char strVhlTypeName[30];

    wRoll = Roll() + wRollMod;

    switch (MechMove(mech)) {
    case MOVE_TRACK:
    strcpy(strVhlTypeName, "tank");
    break;
    case MOVE_WHEEL:
    strcpy(strVhlTypeName, "vehicle");
    wRoll += 2;
    break;
    case MOVE_HOVER:
    strcpy(strVhlTypeName, "hovercraft");
    wRoll += 4;
    break;
    case MOVE_HULL:
    strcpy(strVhlTypeName, "ship");
    break;
    case MOVE_FOIL:
    strcpy(strVhlTypeName, "hydrofoil");
    wRoll += 4;
    break;
    case MOVE_SUB:
    strcpy(strVhlTypeName, "submarine");
    break;
    default:
    strcpy(strVhlTypeName,
        "weird unidentifiable toy (warn a wizard!)");
    break;
    }

    if (wRoll < 8)        /* no effect */
    return;

    mech_notify(mech, MECHALL, "%ch%cyCRITICAL HIT!!%c");

    if (wRoll < 10) {        /* minor effect */
    MechPilotSkillBase(mech) += 1;

    if (Fallen(mech))
        mech_notify(mech, MECHALL,
        "%cr%chYour destroyed motive system takes another hit!%cn");
    else
        mech_notify(mech, MECHALL,
        tprintf
        ("%%cr%%chYour motive system takes a minor hit, making it harder to control your %s!%%cn",
            strVhlTypeName));

    if (MechSpeed(mech) != 0.0)
        MechLOSBroadcast(mech, "wobbles slightly.");
    } else if (wRoll < 12) {    /* moderate effect */
    MechPilotSkillBase(mech) += 2;

    if (Fallen(mech))
        mech_notify(mech, MECHALL,
        "%cr%chYour destroyed motive system takes another hit!%cn");
    else
        mech_notify(mech, MECHALL,
        tprintf
        ("%%cr%%chYour motive system takes a moderate hit, slowing you down and making it harder to control your %s!%%cn",
            strVhlTypeName));

    if (MechSpeed(mech) != 0.0)
        MechLOSBroadcast(mech, "wobbles violently.");

    LowerMaxSpeed(mech, MP1);
    correct_speed(mech);
    } else {
    if (Fallen(mech))
        mech_notify(mech, MECHALL,
        "%cr%chYour destroyed motive system takes another hit!%cn");
    else
        mech_notify(mech, MECHALL,
        tprintf
        ("%%cr%%chYour motive system is destroyed! Your %s can nolonger move!%%cn",
            strVhlTypeName));

    if (MechSpeed(mech) > 0)
        MechLOSBroadcast(mech,
        "shakes violently then begins to slow down.");

    SetMaxSpeed(mech, 0.0);
    MakeMechFall(mech);
    correct_speed(mech);
    }

}

int FindAdvFasaVehicleHitLocation(MECH * mech, int hitGroup,
    int *iscritical, int *isrear)
{
    int roll, hitloc = 0;
    int side;

    *iscritical = 0;
    roll = Roll();

    if (MechStatus(mech) & COMBAT_SAFE)
    return 0;

    if (MechDugIn(mech) && GetSectInt(mech, TURRET) &&
    Number(1, 100) >= 42)
    return TURRET;

    rollstat.hitrolls[roll - 2]++;
    rollstat.tothrolls++;

    switch (MechType(mech)) {
    case CLASS_VEH_GROUND:
    switch (hitGroup) {
    case LEFTSIDE:
    case RIGHTSIDE:
        side = (hitGroup == LEFTSIDE ? LSIDE : RSIDE);

        switch (roll) {
        case 2:
        hitloc = side;
        *iscritical = 1;
        break;
        case 3:
        hitloc = side;
        if (crittable(mech, hitloc, btechconf.btech_critlevel))
            DoMotiveSystemHit(mech, 0);
        break;
        case 4:
        hitloc = side;
        break;
        case 5:
        hitloc = FSIDE;
        break;
        case 6:
        case 7:
        case 8:
        hitloc = side;
        break;
        case 9:
        hitloc = BSIDE;
        break;
        case 10:
        case 11:
        hitloc = CHECK_ZERO_LOC(mech, TURRET, side);
        break;
        case 12:
        hitloc = CHECK_ZERO_LOC(mech, TURRET, side);
        *iscritical = 1;
        break;
        }
        break;

    case FRONT:
    case BACK:
        side = (hitGroup == FRONT ? FSIDE : BSIDE);

        switch (roll) {
        case 2:
        hitloc = side;
        *iscritical = 1;
        break;
        case 3:
        hitloc = side;

        if (crittable(mech, hitloc, btechconf.btech_critlevel))
            DoMotiveSystemHit(mech, 0);
        break;
        case 4:
        hitloc = side;
        break;
        case 5:
        hitloc = (hitGroup == FRONT ? RSIDE : LSIDE);
        break;
        case 6:
        case 7:
        case 8:
        hitloc = side;
        break;
        case 9:
        hitloc = (hitGroup == FRONT ? LSIDE : RSIDE);
        break;
        case 10:
        case 11:
        hitloc =
            CHECK_ZERO_LOC(mech, TURRET,
            (hitGroup == FRONT ? LSIDE : RSIDE));
        break;
        case 12:
        hitloc =
            CHECK_ZERO_LOC(mech, TURRET,
            (hitGroup == FRONT ? LSIDE : RSIDE));
        *iscritical = 1;
        break;
        }
        break;
    }
    break;

    case CLASS_VTOL:
    switch (hitGroup) {
    case LEFTSIDE:
    case RIGHTSIDE:
        side = (hitGroup == LEFTSIDE ? LSIDE : RSIDE);

        switch (roll) {
        case 2:
        hitloc = side;
        *iscritical = 1;
        break;
        case 3:
        case 4:
        hitloc = side;
        break;
        case 5:
        hitloc = FSIDE;
        break;
        case 6:
        case 7:
        case 8:
        hitloc = side;
        break;
        case 9:
        hitloc = BSIDE;
        break;
        case 10:
        case 11:
        hitloc = ROTOR;
        break;
        case 12:
        hitloc = ROTOR;
        *iscritical = 1;
        break;
        }
        break;

    case FRONT:
    case BACK:
        side = (hitGroup == FRONT ? FSIDE : BSIDE);

        switch (roll) {
        case 2:
        hitloc = side;
        *iscritical = 1;
        break;
        case 3:
        hitloc = side;
        break;
        case 4:
        hitloc = side;
        break;
        case 5:
        hitloc = (hitGroup == FRONT ? RSIDE : LSIDE);
        break;
        case 6:
        case 7:
        case 8:
        hitloc = side;
        break;
        case 9:
        hitloc = (hitGroup == FRONT ? LSIDE : RSIDE);
        break;
        case 10:
        case 11:
        hitloc = ROTOR;
        break;
        case 12:
        hitloc = ROTOR;
        *iscritical = 1;
        break;
        }
        break;
    }
    break;
    }

    if (!crittable(mech, hitloc, btechconf.btech_critlevel))
    *iscritical = 0;

    return hitloc;
}

