    int *isrear)
{
    int roll, hitloc = 0;
    int side;

    roll = Roll();

    /* We have a varying set of crit charts we can use, so let's see what's been config'd */
    switch (MechType(mech)) {
    case CLASS_VTOL:
    if (btechconf.btech_fasaadvvtolcrit)
