int FindAreaHitGroup(MECH * mech, MECH * target)
{
    int quadr;

    quadr =
    AcceptableDegree(FindBearing(MechFX(mech), MechFY(mech),
        MechFX(target), MechFY(target)) - MechFacing(target));
#if 1
    if ((quadr >= 135) && (quadr <= 225))
    return FRONT;
    if ((quadr < 45) || (quadr > 315))
    return BACK;
    if ((quadr >= 45) && (quadr < 135))
    return LEFTSIDE;
    return RIGHTSIDE;
#else
    /* These are 'official' BT arcs */
    if (quadr >= 120 && quadr <= 240)
    return FRONT;
    if (quadr < 30 || quadr > 330)
    return BACK;
    if (quadr >= 30 && quadr < 120)
    return LEFTSIDE;
    return RIGHTSIDE;
#endif
}

int FindTargetHitLoc(MECH * mech,
    MECH * target, int *isrear, int *iscritical)
{
    int hitGroup;

/*    *isrear = 0; */
    *iscritical = 0;
    hitGroup = FindAreaHitGroup(mech, target);
    if (hitGroup == BACK)
    *isrear = 1;
    if (MechType(target) == CLASS_MECH &&
    (MechStatus(target) & PARTIAL_COVER))
    return FindPunchLocation(hitGroup);
    if (MechType(mech) == CLASS_MW && MechType(target) == CLASS_MECH &&
    MechZ(mech) <= MechZ(target))
    return FindKickLocation(hitGroup);
    if (MechType(target) == CLASS_MECH &&
    ((MechType(mech) == CLASS_BSUIT &&
        MechSwarmTarget(mech) == target->mynum)))
    return FindSwarmHitLocation(iscritical, isrear);
    return FindHitLocation(target, hitGroup, iscritical, isrear);
}

int findNARCHitLoc(MECH * mech, MECH * hitMech, int *tIsRearHit)
{
    int tIsRear = 0;
    int tIsCritical = 0;
    int wHitLoc = FindTargetHitLoc(mech, hitMech, &tIsRear, &tIsCritical);

    while (GetSectInt(hitMech, wHitLoc) <= 0) {
    wHitLoc = TransferTarget(hitMech, wHitLoc);
    if (wHitLoc < 0)
        return -1;
    }

    *tIsRearHit = 0;
    if (tIsRear) {
    if (MechType(hitMech) == CLASS_MECH)
        *tIsRearHit = 1;
    else if (wHitLoc == FSIDE)
        wHitLoc = BSIDE;
    }

    return wHitLoc;
}

int FindTCHitLoc(MECH * mech, MECH * target, int *isrear, int *iscritical)
{
    int hitGroup;

    *isrear = 0;
    *iscritical = 0;
    hitGroup = FindAreaHitGroup(mech, target);
    if (hitGroup == BACK)
    *isrear = 1;
    if (MechAimType(mech) == MechType(target) && Number(1, 6) >= 3)
    switch (MechType(target)) {
    case CLASS_MECH:
    case CLASS_MW:
        switch (MechAim(mech)) {
        case RARM:
        if (hitGroup != LEFTSIDE)
            return RARM;
        break;
        case LARM:
        if (hitGroup != RIGHTSIDE)
            return LARM;
        break;
        case RLEG:
        if (hitGroup != LEFTSIDE &&
            !(MechStatus(target) & PARTIAL_COVER))
            return RLEG;
        break;
        case LLEG:
        if (hitGroup != RIGHTSIDE &&
            !(MechStatus(target) & PARTIAL_COVER))
            return LLEG;
        break;
        case RTORSO:
        if (hitGroup != LEFTSIDE)
            return RTORSO;
        break;
        case LTORSO:
        if (hitGroup != RIGHTSIDE)
            return LTORSO;
        break;
        case CTORSO:

/*        if (hitGroup != LEFTSIDE && hitGroup != RIGHTSIDE) */
        return CTORSO;
        case HEAD:
        if (Immobile(target))
            return HEAD;
        }
        break;
    case CLASS_AERO:
    case CLASS_DS:
        switch (MechAim(mech)) {
        case AERO_NOSE:
        if (hitGroup != BACK)
            return AERO_NOSE;
        break;
        case AERO_LWING:
        if (hitGroup != RIGHTSIDE)
            return AERO_LWING;
        break;
        case AERO_RWING:
        if (hitGroup != LEFTSIDE)
            return AERO_RWING;
        break;
        case AERO_COCKPIT:
        if (hitGroup != BACK)
            return AERO_COCKPIT;
        break;
        case AERO_FUSEL:
        if (hitGroup != FRONT)
            return AERO_FUSEL;
        break;
        case AERO_ENGINE:
        if (hitGroup != FRONT)
            return AERO_ENGINE;
        break;
        }
    case CLASS_VEH_GROUND:
    case CLASS_VEH_NAVAL:
    case CLASS_VTOL:
        switch (MechAim(mech)) {
        case RSIDE:
        if (hitGroup != LEFTSIDE)
            return (RSIDE);
        break;
        case LSIDE:
        if (hitGroup != RIGHTSIDE)
            return (LSIDE);
        break;
        case FSIDE:
        if (hitGroup != BACK)
            return (FSIDE);
        break;
        case BSIDE:
        if (hitGroup != FRONT)
            return (BSIDE);
        break;
        case TURRET:
        return (TURRET);
        break;
        }
        break;
    }
    if (MechType(target) == CLASS_MECH &&
    (MechStatus(target) & PARTIAL_COVER))
    return FindPunchLocation(hitGroup);
    return FindHitLocation(target, hitGroup, iscritical, isrear);
}

int FindAimHitLoc(MECH * mech, MECH * target, int *isrear, int *iscritical)
{
    int hitGroup;

    *isrear = 0;
    *iscritical = 0;
    hitGroup = FindAreaHitGroup(mech, target);
    if (hitGroup == BACK)
    *isrear = 1;
    if (MechType(target) == CLASS_MECH || MechType(target) == CLASS_MW)
    switch (MechAim(mech)) {
    case RARM:
        if (hitGroup != LEFTSIDE)
        return (RARM);
        break;
    case LARM:
        if (hitGroup != RIGHTSIDE)
        return (LARM);
        break;
    case RLEG:
        if (hitGroup != LEFTSIDE &&
        !(MechStatus(target) & PARTIAL_COVER))
        return (RLEG);
        break;
    case LLEG:
        if (hitGroup != RIGHTSIDE &&
        !(MechStatus(target) & PARTIAL_COVER))
        return (LLEG);
        break;
    case RTORSO:
        if (hitGroup != LEFTSIDE)
        return (RTORSO);
        break;
    case LTORSO:
        if (hitGroup != RIGHTSIDE)
        return (LTORSO);
        break;
    case CTORSO:
        return (CTORSO);
    case HEAD:
        return (HEAD);
    } else if (is_aero(target))
    return MechAim(mech);
    else
    switch (MechAim(mech)) {
    case RSIDE:
        if (hitGroup != LEFTSIDE)
        return (RSIDE);
        break;
    case LSIDE:
        if (hitGroup != RIGHTSIDE)
        return (LSIDE);
        break;
    case FSIDE:
        if (hitGroup != BACK)
        return (FSIDE);
        break;
    case BSIDE:
        if (hitGroup != FRONT)
        return (BSIDE);
        break;
    case TURRET:
        return (TURRET);
        break;
    }

    if (MechType(target) == CLASS_MECH &&
    (MechStatus(target) & PARTIAL_COVER))
    return FindPunchLocation(hitGroup);
    return FindHitLocation(target, hitGroup, iscritical, isrear);
}

#include <cstdio>
#include <cstdlib>

#define MAX_ELEMENT_COUNT 1000000

using namespace std;

int d[MAX_ELEMENT_COUNT];

void qsort(int l, int r)
{
	if (l < r)
	{
		int x = d[r];
		int j = l - 1;

		for (int i = l; i <= r; i++)
		{
			if (d[i] <= x)
			{
				j++;
				int temp = d[i];
				d[i] = d[j];
				d[j] = temp;
			}
		}

		qsort(l, j - 1);
		qsort(j + 1, r);
	}
}

int main()
{
	for (int i = 0; i < MAX_ELEMENT_COUNT; i++)
	{
		d[i] = rand();
	}

	qsort(0, MAX_ELEMENT_COUNT - 1);

	for (int i = 0; i < MAX_ELEMENT_COUNT; i++)
	{
		printf("%d\n", d[i]);
	}

	return 0;
}

