namespace modules {
namespace external_commands {
class processing {
 public:
  processing();
  ~processing() throw();
  bool execute(std::string const& cmd) const;
  bool is_thread_safe(char const* cmd) const;

 private:
  struct command_info {
    command_info(int _id = 0,
                 void (*_func)(int, time_t, char*) = NULL,
                 bool is_thread_safe = false)
        : id(_id), func(_func), thread_safe(is_thread_safe) {}
    ~command_info() throw() {}
    int id;
    void (*func)(int id, time_t entry_time, char* args);
    bool thread_safe;
  };

  static void _wrapper_read_state_information();
  static void _wrapper_save_state_information();
  static void _wrapper_enable_host_and_child_notifications(host* hst);
  static void _wrapper_disable_host_and_child_notifications(host* hst);
  static void _wrapper_enable_all_notifications_beyond_host(host* hst);
  static void _wrapper_disable_all_notifications_beyond_host(host* hst);
  static void _wrapper_enable_host_svc_notifications(host* hst);
  static void _wrapper_disable_host_svc_notifications(host* hst);
  static void _wrapper_enable_host_svc_checks(host* hst);
  static void _wrapper_disable_host_svc_checks(host* hst);
  static void _wrapper_set_host_notification_number(host* hst, char* args);
  static void _wrapper_send_custom_host_notification(host* hst, char* args);
  static void _wrapper_enable_service_notifications(host* hst);
  static void _wrapper_disable_service_notifications(host* hst);
  static void _wrapper_enable_service_checks(host* hst);
  static void _wrapper_disable_service_checks(host* hst);
  static void _wrapper_enable_passive_service_checks(host* hst);
  static void _wrapper_disable_passive_service_checks(host* hst);
  static void _wrapper_set_service_notification_number(service* svc,
                                                       char* args);
  static void _wrapper_send_custom_service_notification(service* svc,
                                                        char* args);

  template <void (*fptr)()>
  static void _redirector(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;
    (void)args;
    (*fptr)();
  }

  template <int (*fptr)()>
  static void _redirector(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;
    (void)args;
    (*fptr)();
  }

  template <void (*fptr)(int, char*)>
  static void _redirector(int id, time_t entry_time, char* args) {
    (void)entry_time;
    (*fptr)(id, args);
  }

  template <int (*fptr)(int, char*)>
  static void _redirector(int id, time_t entry_time, char* args) {
    (void)entry_time;
    (*fptr)(id, args);
  }

  template <int (*fptr)(int, time_t, char*)>
  static void _redirector(int id, time_t entry_time, char* args) {
    (*fptr)(id, entry_time, args);
  }

  template <void (*fptr)(host*)>
  static void _redirector_host(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;

    char* name(my_strtok(args, ";"));

    host* hst{nullptr};
    host_map::const_iterator it(host::hosts.find(name));
    if (it != host::hosts.end())
      hst = it->second.get();

    if (!hst)
      return;
    (*fptr)(hst);
  }

  template <void (*fptr)(host*, char*)>
  static void _redirector_host(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;

    char* name(my_strtok(args, ";"));

    host* hst{nullptr};
    host_map::const_iterator it(host::hosts.find(name));
    if (it != host::hosts.end())
      hst = it->second.get();

    if (!hst)
      return;
    (*fptr)(hst, args + strlen(name) + 1);
  }

  template <void (*fptr)(host*)>
  static void _redirector_hostgroup(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;

    char* group_name(my_strtok(args, ";"));

    hostgroup* group(nullptr);
    hostgroup_map::const_iterator it{hostgroup::hostgroups.find(group_name)};
    if (it != hostgroup::hostgroups.end())
      group = it->second.get();
    if (!group)
      return;

    for (host_map_unsafe::iterator it(group->members.begin()),
         end(group->members.begin());
         it != end; ++it)
      if (it->second)
        (*fptr)(it->second);
  }

  template <void (*fptr)(service*)>
  static void _redirector_service(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;

    char* name(my_strtok(args, ";"));
    char* description(my_strtok(NULL, ";"));

    service_map::const_iterator found(
        service::services.find({name, description}));

    if (found == service::services.end() || !found->second)
      return;
    (*fptr)(found->second.get());
  }

  template <void (*fptr)(service*, char*)>
  static void _redirector_service(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;

    char* name{my_strtok(args, ";")};
    char* description{my_strtok(NULL, ";")};
    service_map::const_iterator found{
        service::services.find({name, description})};

    if (found == service::services.end() || !found->second)
      return;
    (*fptr)(found->second.get(), args + strlen(name) + strlen(description) + 2);
  }

  template <void (*fptr)(service*)>
  static void _redirector_servicegroup(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;

    char* group_name(my_strtok(args, ";"));
    servicegroup_map::const_iterator sg_it{
        servicegroup::servicegroups.find(group_name)};
    if (sg_it == servicegroup::servicegroups.end() || !sg_it->second)
      return;

    for (service_map_unsafe::iterator it2(sg_it->second->members.begin()),
         end2(sg_it->second->members.end());
         it2 != end2; ++it2)
      if (it2->second)
        (*fptr)(it2->second);
  }

  template <void (*fptr)(host*)>
  static void _redirector_servicegroup(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;

    char* group_name(my_strtok(args, ";"));
    servicegroup_map::const_iterator sg_it{
        servicegroup::servicegroups.find(group_name)};
    if (sg_it == servicegroup::servicegroups.end() || !sg_it->second)
      return;

    host* last_host{nullptr};
    for (service_map_unsafe::iterator it2(sg_it->second->members.begin()),
         end2(sg_it->second->members.end());
         it2 != end2; ++it2) {
      host* hst{nullptr};
      host_map::const_iterator found(host::hosts.find(it2->first.first));
      if (found != host::hosts.end())
        hst = found->second.get();

      if (!hst || hst == last_host)
        continue;
      (*fptr)(hst);
      last_host = hst;
    }
  }

  template <void (*fptr)(contact*)>
  static void _redirector_contact(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;

    char* name(my_strtok(args, ";"));
    contact_map::const_iterator ct_it{contact::contacts.find(name)};
    if (ct_it == contact::contacts.end())
      return;
    (*fptr)(ct_it->second.get());
  }

  template <void (*fptr)(char*)>
  static void _redirector_file(int id __attribute__((unused)),
                               time_t entry_time __attribute__((unused)),
                               char* args) {
    char* filename(my_strtok(args, ";"));
    (*fptr)(filename);
  }

  template <void (*fptr)(contact*)>
  static void _redirector_contactgroup(int id, time_t entry_time, char* args) {
    (void)id;
    (void)entry_time;

    char* group_name(my_strtok(args, ";"));
    contactgroup_map::iterator it_cg{
        contactgroup::contactgroups.find(group_name)};
    if (it_cg == contactgroup::contactgroups.end() || !it_cg->second)
      return;

    for (contact_map_unsafe::const_iterator
             it(it_cg->second->get_members().begin()),
         end(it_cg->second->get_members().end());
         it != end; ++it)
      if (it->second)
        (*fptr)(it->second);
  }

  std::unordered_map<std::string, command_info> _lst_command;
  mutable std::mutex _mutex;
};
