uint32_t Chunker::cutPoint(const uint8_t* src, const uint32_t len) {
    uint32_t n;
    uint32_t fp = 0;
    uint32_t i;
    i = std::min(len, static_cast<uint32_t>(minChunkSize)); 
    n = std::min(normalSize_, len);
    for (; i < n; i++) {
        fp = (fp >> 1) + GEAR[src[i]];
        if (!(fp & maskS_)) {
            return (i + 1);
        }
    }

    n = std::min(static_cast<uint32_t>(maxChunkSize), len);
    for (; i < n; i++) {
        fp = (fp >> 1) + GEAR[src[i]];
        if (!(fp & maskL_)) {
            return (i + 1);
        }
    } 
    return i;
}

