          //Copy our data from std::vector into allocated memory region
          for (int y = 0; y < img.rows(); y++) {
            png_byte* row = rowPointers[y];
            for (int x = 0; x < img.cols(); x++) {
              int offset;
              offset = y * img.cols() + x;
              row[x * nChannels] = ptr[offset];
