		{
			CAutoTrace at(m_pmp);
			at.Os() << "MEMO after implementation (stage " << m_ulCurrSearchStage << ")" << std::endl;
		}

		{
			CAutoTrace at(m_pmp);
			at.Os() << *this;
		}
	}

	if (GPOS_FTRACE(EopttracePrintOptimizationStatistics))
	{
		CAutoTrace at(m_pmp);
		(void) OsPrintMemoryConsumption(at.Os(), "Memory consumption after implementation ");
	}
