IOstream &
CEngine::OsPrintMemoryConsumption
	(
	IOstream &os,
	const CHAR *szHeader
	)
	const
{
	CMDAccessor *pmda = COptCtxt::PoctxtFromTLS()->Pmda();
	CMDAccessor::MDCache *pcache = pmda->Pcache();

	os << std::endl << szHeader
