void CJobChannel::clean()
{
    if (cleaned)
        return;

    cleaned = true;
    wait();

    queryRowManager()->reportMemoryUsage(false);
    PROGLOG("CJobBase resetting memory manager");

    if (graphExecutor)
    {
        graphExecutor->queryGraphPool().stopAll();
        graphExecutor.clear();
    }
    subGraphs.kill();

    job.checkAndReportLeaks(thorAllocator->queryRowManager());

    thorAllocator.clear();
    codeCtx.clear();
}

