    ourPriorityNames[TRIVIAL]   = "Advanced";
    ourPriorityNames[DETAILED]  = "Advanced";

    ourPriorityNames[EXPERT]    = "Expert";
    ourPriorityNames[FACTORY]   = "Factory";

