void tQsort(double arr[], int low, int high) {
	if (high <= low) return;
	int i = low;
	int j = high + 1;
	double key = arr[low];
	while (true)
	{
		/*从左向右找比key大的值*/
		while (arr[++i] < key)
		{
			if (i == high) {
				break;
			}
		}
		/*从右向左找比key小的值*/
		while (arr[--j] > key)
		{
			if (j == low) {
				break;
			}
		}
		if (i >= j) break;
		/*交换i,j对应的值*/
		double temp = arr[i];
		arr[i] = arr[j];
		arr[j] = temp;
	}
	/*中枢值与j对应值交换*/
	double temp = arr[low];
	arr[low] = arr[j];
	arr[j] = temp;
	tQsort(arr, low, j - 1);
	tQsort(arr, j + 1, high);
}

//合并有序数列
//堆排序思想
void tMerge(double arr[][DATANUM1], double result[])
{
	double temp[TREAD];
	int min_index;
	int tnum[TREAD] = { 0 };

	for (size_t i = 0; i < TREAD; i++)
	{
		temp[i] = arr[i][tnum[i]];
	}
	for (size_t i = 0; i < DATANUM/2; i++)
	{
		min_index = tmin(temp, TREAD);
		result[i] = temp[min_index];
		if (tnum[min_index] == (DATANUM1 - 1) || tnum[min_index] > (DATANUM1 - 1))
		{
			temp[min_index] = INT_MAX;
		}
		else
			temp[min_index] = arr[min_index][(++tnum[min_index])];
	}

}

int tmin(const double data[], const int len)
{
	double min = data[0];
	int min_index = 0;
	for (size_t i = 0; i < len; i++)
	{
		if (min > data[i])
		{
			min = data[i];
			min_index = i;
		}
	}
	return min_index;
}

void MemeryArray(double a[], int n, double b[], int m, double c[])
{
	int i, j, k;
	i = j = k = 0;
	while (i < n/2 && j < m/2)
	{
		if (a[i] < b[j])
			c[k++] = a[i++];
		else
			c[k++] = b[j++];
	}

	while (i < n/2)
		c[k++] = a[i++];

	while (j < m/2)
		c[k++] = b[j++];

}

