{
  std::string s;
  switch(m_iWeaponType)
  {
  case type_rail_gun:
    s="RG: ";break;
  case type_rocket_launcher:
    s="RL: "; break;
  case type_shotgun:
    s="SG: "; break;
  }

  gdi->TextAtPos(Position, s + ttos(CalculateDesirability(pBot), 2));
}

