dmz::RenderModuleIsectOSG::RenderModuleIsectOSG (
      const PluginInfo &Info,
      const Config &Local) :
      Plugin (Info),
      RenderModuleIsect (Info),
      _log (Info),
      _core (0),
      _defaultIsectMask (0) {

   _init (Local);
