        0.2,
        0.1,
        0.33,
        0.44,
        // batch 1, class 0
        0.2,
        0.1,
        0.4,
        0.2,
        0.1,
        0.05,
        0.2,
        0.25,
        // batch 1, class 1
        0.1,
        0.2,
        0.5,
        0.3,
        0.1,
        0.1,
        0.12,
