int accept(int fd, struct sockaddr *__restrict addr_ptr, socklen_t *__restrict addr_length) {
	if(addr_ptr || addr_length)
		mlibc::infoLogger() << "\e[35mmlibc: accept() does not fill struct sockaddr\e[39m"
				<< frg::endlog;
	int newfd;
	if(!mlibc::sys_accept) {
		MLIBC_MISSING_SYSDEP();
