void genericEntity::Update(double dt)
{
    static const float ENTITY_SPEED = 20.f;
    position = position + view * (float)(velocity * dt);
    if (this->velocity > 0)
    {
        this->velocity -= (float)(1.0f * dt);
    }
    if (this->SoundSrc != nullptr)
    {
        this->SoundSrc->updatePos(&this->position);
    }
}

