// 4. высвобождаем старый участок памяти меньшего размера
        delete[] data_;

// 5. пересылаем указатель на новый участок памяти
        data_ = new_data;

// 6. не забываем посолить ... кхм... обновить емкость массива
        capacity_ = new_capacity;
