    if ( a( i1 ) != b( i0, i1 + range.first ) ) errors++;
  }

  if ( errors > 0 ) {
    std::cout << "Error Suviews test_Check1D2D: " << errors << std::endl;
  }

  ASSERT_TRUE( errors == 0 );
}

