        jvParams[jss::MUSO_state][jss::accounts] = Json::arrayValue;
        jvParams[jss::MUSO_state][jss::accounts].append(acct_a.human());
        jvParams[jss::MUSO_state][jss::accounts].append(acct_b.human());
        return env.rpc(
            "json", "ledger_entry", to_string(jvParams))[jss::result];
    }

    static auto
    ledgerEntryRoot(jtx::Env& env, jtx::Account const& acct)
    {
        Json::Value jvParams;
        jvParams[jss::ledger_index] = "current";
        jvParams[jss::account_root] = acct.human();
        return env.rpc(
            "json", "ledger_entry", to_string(jvParams))[jss::result];
    }

    static auto
    ledgerEntryOffer(
        jtx::Env& env,
