void Entity::move(Direction dir)
{
	switch(dir)
	{
		case DIR_UP: case DIR_DOWN: case DIR_LEFT: case DIR_RIGHT:
			bool success = false;
			Position newPosition = getPossibleMovePosition(getPosition(), dir, success);
			if (success)
			{
				clear();
				setPosition(newPosition);
				display();
			}
			break;

	}
}

