 *		  
 * ********************************************************************/
void Trace::SetTraceCFG() {

	/* set default params */					
	MaxLen_ = 1000;
	MaxStep_ = 0.05;
	InitStep_ = 0.01;
	MinStep_ = 0.001;
	Verbose_ = false;
