/***********************************************************************
 * NAME : void Trace_CalcualteTraceDist()
 * 
 * DESCRIPTION : Calcualtes the distance along all field lines.
 *		  
 * ********************************************************************/
void Trace::_CalculateTraceDist() {
	int i, j;
	double dx, dy, dz;
	for (i=0;i<n_;i++) {
		S_[i][0] = 0.0;
		for (j=1;j<nstep_[i];j++) {
			dx = x_[i][j] - x_[i][j-1];
			dy = y_[i][j] - y_[i][j-1];
			dz = z_[i][j] - z_[i][j-1];
			S_[i][j] = S_[i][j-1] + sqrt(dx*dx + dy*dy + dz*dz);
		}
	}
	setDist_ = true;
}


