    SET_UNIFORM( "t0", osg::Uniform::FLOAT_VEC2, t0 );
    SET_UNIFORM( "t1", osg::Uniform::FLOAT_VEC2, t1 );
    SET_UNIFORM( "t2", osg::Uniform::FLOAT_VEC2, t2 );

