void crivo(){
    bs.set();
    bs[0] = bs[1] = 0;
    fore(i, 2, sizec){
        if(bs[i]){
            for(int j=i*i; j<sizec; j+=i) bs[j] = 0;
            primes.push_back(i);
        }
    }
}

int main(){

