        if(bs[i]) num[i] = i+1;
        else{
            fore(j, 0, primes.size()){
                if(i%primes[j] == 0){ add = primes[j]; val = i/primes[j]; break; }
            }
            num[i] = add + num[val];
        }
    }

    /*fore(i, 1, sizec){
