	int maxIdx = -1, maxPenalty = 0;
	for (int i = 0; i < (int)penalty.size(); ++i)
		maxIdx = (penalty[i] > maxPenalty)? i : maxIdx;
	graph.roads[maxIdx].penalty *= 10;
	 */
}


