	Log log_tasks(Log::LogLevelWarning);
	for (int i = 0; i < m_current_tasks.size(); i++)
	{
		if (std::get<2>(m_current_tasks[i]) == 0)
		{
			Actor* agent = std::get<1>(m_current_tasks[i]);
