				continue;
			}

			public_buildings.clear();
			switch (location_type)
			{
			case 0:
				for (int i = 0; i < m_tiles[a]->Pub_buildings.size(); i++)
				{
					if (m_tiles[a]->Pub_buildings[i]->Get_Type() == Public_Buildings::Hospital)
