template<typename IBaseInterface>
BOOL TShaderVariable<IBaseInterface>::IsValid()
{
    UINT numElements = IsArray()? pType->Elements : 1;
    BOOL valid = TRUE;
    while( numElements > 0 && ( valid = Data.pShader[ numElements-1 ].IsValid ) )
        numElements--;
    return valid;
}

