                                m_nSequence = RandomSequence1(SEQUENCE_BUTTERFLY_DRAW, SEQUENCE_BUTTERFLY_DRAW2);
                                break;
                            case SEQUENCE_DEFAULT_LOOKAT01:
                                m_nSequence = RandomSequence1(SEQUENCE_BUTTERFLY_LOOKAT01, 14);
                                break;
                            default:
