  double cost0 = cost->evalTerminalCost(robot_, data, grid_info, s);
  cost->evalTerminalCostDerivatives(robot_, data, grid_info, s, kkt_residual);
  auto s1 = s;
  Eigen::VectorXd lq_ref(dimv);
  for (int i=0; i<dimv; ++i) {
