  Eigen::VectorXd lv_ref(dimv);
  for (int i=0; i<dimv; ++i) {
    s1 = s;
    s1.v(i) += finite_diff_;
    robot_.updateKinematics(s1.q, s1.v);
    lv_ref(i) = (cost->evalTerminalCost(robot_, data, grid_info, s1) - cost0) / finite_diff_;
