#ifndef NT2_TOOLBOX_LINALG_FUNCTIONS_COV_HPP_INCLUDED
#define NT2_TOOLBOX_LINALG_FUNCTIONS_COV_HPP_INCLUDED

#include <nt2/include/functor.hpp>
#include <nt2/include/functions/sqr_abs.hpp>
