			{
				pddl::Tokenizer tokenizer;
				tokenizer.read(domainFile);
				pddl::Context context(std::move(tokenizer), ignoreWarnings, pddl::Mode::Compatibility);

				CHECK_NOTHROW(pddl::parseDescription(context));
