#define le 1003
vector <int> v[le];
vector<int> ct;
int dis[le];
bool vis[le];
void bfs(int a){
  memset(vis, false, sizeof(vis));
  vis[a] = true;
  dis[a]++;
  queue<int> q;
  q.push(a);
  while(!q.empty()){
    int p = q.front();
    q.pop();
    for(int i = 0; i < v[p].size(); i++){
      int e = v[p][i];
      if(vis[e] == false){
        vis[e] = true;
        dis[e]++;
        q.push(e);
      }
    }
  }
}
