      if (itrechit == EBhits->end()) {
        //	std::cout << "EB DetId not in e25" << std::endl;
        energy.push_back(0.);
        energy5x5 += 0.;
        continue;
      }

      if (edm::isNotFinite(itrechit->energy())) {
        std::cout << " nan energy " << std::endl;
