      //Summing in 3x3 to cut later on:
      for (int tt = 0; tt < 9; tt++) {
        if (NxNaroundMax[icry] == S9aroundMax[tt])
          energy3x3 += itrechit->energy();
      }
    }
  }
  //  if((read_events-50)%10000 ==0)cout << "++++++++++++ENERGY 5x5 " <<  energy5x5 << std::endl;
