    return;

  if (maxHitId.subdetId() == EcalBarrel) {
    GeneralMapBeforePt->Fill(maxCC_Eta, maxCC_Phi);
  } else {
    if (Zside < 0) {
      GeneralMapEndCapMinusBeforePt->Fill(maxCC_Eta, maxCC_Phi);
