	mytexture->gradientBL[1] = 255; // G
	mytexture->gradientBL[2] = 255; // B
	mytexture->gradientBL[3] = 255; // A
	mytexture->gradientBR[0] = 255; // R
	mytexture->gradientBR[1] = 255; // G
	mytexture->gradientBR[2] = 255; // B
