  // Underlying native SIMD vector getter
  simd_vectorl native_register() const { return car; }

  typedef T value_type;
  typedef SimdExt simd_ext;
  static const int unroll = 1;
};

template <typename T, int N, typename SimdExt>
NSIMD_STRUCT packl {
