            {
                string s(
                    make_input_iterator(t.v2.begin()),
                    make_input_iterator(t.v2.end()));
                BOOST_TEST(s == t.v2);
            }
        }

        // string(string)
        {
            {
                string const s0(t.v1);
                string s(s0);
                BOOST_TEST(s == t.v1);
