    void
    testElementAccess()
    {
        test_vectors const t;

        string s1(t.v1);
        string s2(t.v2);
        auto const& cs1(s1);
        auto const& cs2(s2);

        // at(size_type)
        {
            BOOST_TEST(s1.at(1) == 'b');
            s1.at(1) = '*';
            BOOST_TEST(s1.at(1) == '*');
            s1.at(1) = 'b';
            BOOST_TEST(s1.at(1) == 'b');

            BOOST_TEST(s2.at(1) == 'B');
            s2.at(1) = '*';
            BOOST_TEST(s2.at(1) == '*');
            s2.at(1) = 'B';
            BOOST_TEST(s2.at(1) == 'B');

            BOOST_TEST_THROWS(s1.at(s2.size()),
                std::out_of_range);
        }

        // at(size_type) const
        {
            BOOST_TEST(cs1.at(1) == 'b');
            BOOST_TEST(cs2.at(1) == 'B');

            BOOST_TEST_THROWS(cs1.at(cs2.size()),
                std::out_of_range);
        }

        // operator[&](size_type)
        {
            BOOST_TEST(s1[1] == 'b');
            s1[1] = '*';
            BOOST_TEST(s1[1] == '*');
            s1[1] = 'b';
            BOOST_TEST(s1[1] == 'b');

            BOOST_TEST(s2[1] == 'B');
            s2[1] = '*';
            BOOST_TEST(s2[1] == '*');
            s2[1] = 'B';
            BOOST_TEST(s2[1] == 'B');
        }

        // operator[&](size_type) const
        {
            BOOST_TEST(cs1[1] == 'b');
            BOOST_TEST(cs2[1] == 'B');
        }

        // front()
        {
            BOOST_TEST(s1.front() == 'a');
            s1.front() = '*';
            BOOST_TEST(s1.front() == '*');
            s1.front() = 'a';
            BOOST_TEST(s1.front() == 'a');

            BOOST_TEST(s2.front() == 'A');
            s2.front() = '*';
            BOOST_TEST(s2.front() == '*');
            s2.front() = 'A';
            BOOST_TEST(s2.front() == 'A');
        }

        // front() const
        {
            BOOST_TEST(cs1.front() == 'a');
            BOOST_TEST(cs2.front() == 'A');
        }

        // back()
        {
            auto const ch1 = s1.at(s1.size()-1);
            auto const ch2 = s2.at(s2.size()-1);

            BOOST_TEST(s1.back() == ch1);
            s1.back() = '*';
            BOOST_TEST(s1.back() == '*');
            s1.back() = ch1;
            BOOST_TEST(s1.back() == ch1);

            BOOST_TEST(s2.back() == ch2);
            s2.back() = '*';
            BOOST_TEST(s2.back() == '*');
            s2.back() = ch2;
            BOOST_TEST(s2.back() == ch2);
        }

        // back() const
        {
            auto const ch1 = s1.at(s1.size()-1);
            auto const ch2 = s2.at(s2.size()-1);

            BOOST_TEST(cs1.back() == ch1);
            BOOST_TEST(cs2.back() == ch2);
        }

        // data()
        {
            BOOST_TEST(
                string_view(s1.data()) == t.v1);
            BOOST_TEST(
                string_view(s2.data()) == t.v2);
        }
        // data() const
        {
            BOOST_TEST(
                string_view(cs1.data()) == t.v1);
