        }

        // operator string_view()
        {
            BOOST_TEST(
                string_view(cs1) == t.v1);
            BOOST_TEST(
                string_view(cs2) == t.v2);
        }
    }

    void
    testIterators()
    {
        string s = "abc";
        auto const& ac(s);

        {
            auto it = s.begin();
            BOOST_TEST(*it == 'a'); ++it;
            BOOST_TEST(*it == 'b');   it++;
            BOOST_TEST(*it == 'c'); ++it;
            BOOST_TEST(it == s.end());
        }
        {
            auto it = s.cbegin();
            BOOST_TEST(*it == 'a'); ++it;
            BOOST_TEST(*it == 'b');   it++;
            BOOST_TEST(*it == 'c'); ++it;
            BOOST_TEST(it == s.cend());
        }
        {
            auto it = ac.begin();
            BOOST_TEST(*it == 'a'); ++it;
            BOOST_TEST(*it == 'b');   it++;
            BOOST_TEST(*it == 'c'); ++it;
            BOOST_TEST(it == ac.end());
        }
        {
            auto it = s.end();
            --it; BOOST_TEST(*it == 'c');
            it--; BOOST_TEST(*it == 'b');
            --it; BOOST_TEST(*it == 'a');
            BOOST_TEST(it == s.begin());
        }
        {
            auto it = s.cend();
            --it; BOOST_TEST(*it == 'c');
            it--; BOOST_TEST(*it == 'b');
            --it; BOOST_TEST(*it == 'a');
            BOOST_TEST(it == s.cbegin());
        }
        {
            auto it = ac.end();
            --it; BOOST_TEST(*it == 'c');
            it--; BOOST_TEST(*it == 'b');
            --it; BOOST_TEST(*it == 'a');
            BOOST_TEST(it == ac.begin());
        }

        {
            auto it = s.rbegin();
            BOOST_TEST(*it == 'c'); ++it;
            BOOST_TEST(*it == 'b');   it++;
            BOOST_TEST(*it == 'a'); ++it;
            BOOST_TEST(it == s.rend());
        }
        {
            auto it = s.crbegin();
            BOOST_TEST(*it == 'c'); ++it;
            BOOST_TEST(*it == 'b');   it++;
            BOOST_TEST(*it == 'a'); ++it;
            BOOST_TEST(it == s.crend());
        }
        {
            auto it = ac.rbegin();
            BOOST_TEST(*it == 'c'); ++it;
            BOOST_TEST(*it == 'b');   it++;
            BOOST_TEST(*it == 'a'); ++it;
            BOOST_TEST(it == ac.rend());
        }
        {
            auto it = s.rend();
            --it; BOOST_TEST(*it == 'a');
            it--; BOOST_TEST(*it == 'b');
            --it; BOOST_TEST(*it == 'c');
            BOOST_TEST(it == s.rbegin());
        }
        {
            auto it = s.crend();
            --it; BOOST_TEST(*it == 'a');
            it--; BOOST_TEST(*it == 'b');
            --it; BOOST_TEST(*it == 'c');
            BOOST_TEST(it == s.crbegin());
        }
        {
            auto it = ac.rend();
            --it; BOOST_TEST(*it == 'a');
            it--; BOOST_TEST(*it == 'b');
            --it; BOOST_TEST(*it == 'c');
            BOOST_TEST(it == ac.rbegin());
        }

        {
            string s2;
            string const& cs2(s2);
            BOOST_TEST(std::distance(
                s2.begin(), s2.end()) == 0);
            BOOST_TEST(std::distance(
                cs2.begin(), cs2.end()) == 0);
            BOOST_TEST(std::distance(
                s2.rbegin(), s2.rend()) == 0);
            BOOST_TEST(std::distance(
                cs2.rbegin(), cs2.rend()) == 0);
        }
    }

    void
    testCapacity()
    {
        test_vectors const t;

        // empty()
        {
            {
                string s;
                BOOST_TEST(s.empty());
            }
            {
                string s = "abc";
                BOOST_TEST(! s.empty());
            }
        }

        // size()
        // max_size()
        {
            string s = "abc";
            BOOST_TEST(s.size() == 3);
            BOOST_TEST(s.max_size() < string::npos);
        }

        // reserve(size_type)
        {
            fail_loop([&](storage_ptr const& sp)
            {
                string s(sp);
                s.append(t.v1);
                s.append(t.v2);

                s.reserve(0);
                BOOST_TEST(s.size() ==
                    t.v1.size() + t.v2.size());

                s.reserve(t.v1.size() + t.v2.size());
                BOOST_TEST(s.size() ==
                    t.v1.size() + t.v2.size());

                s.reserve(s.size() * 2);
                BOOST_TEST(s.capacity() >
                    t.v1.size() + t.v2.size());

                s.resize(t.v1.size());
                s.reserve(t.v1.size());
                BOOST_TEST(s == t.v1);
            });
        }

        // capacity()
        {
            // implied
        }

        // shrink_to_fit()
        fail_loop([&](storage_ptr const& sp)
        {
            string s(sp);
            string::size_type cap;

            cap = s.capacity();
            s.shrink_to_fit();
            BOOST_TEST(s.capacity() == cap);

            s.reserve(s.capacity() + 1);
            s.shrink_to_fit();
            BOOST_TEST(s.capacity() == cap);

            s.resize(cap * 3, '*');
            cap = s.capacity();
            s.resize(cap - 1);
            s.shrink_to_fit();
            BOOST_TEST(s.capacity() == cap);

            s.resize(cap / 2);
            BOOST_TEST(s.capacity() == cap);

            s.shrink_to_fit();
            BOOST_TEST(s.capacity() < cap);
        });
