                BOOST_TEST(s2.replace(0, 4, t.v2.substr(4, 2)) == 
                           s1.replace(0, 4, t.v2.data() + 4, 2));
            });

            // outside, grow
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(s2.replace(0, 1, t.v2.substr(0)) == 
                           s1.replace(0, 1, t.v2.data(), t.v2.size()));
            });

            // outside, grow, reallocate
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                s1.append(s1);
                s2.append(s2);
                BOOST_TEST(s2.replace(0, 1, t.v2.substr(0)) == 
                           s1.replace(0, 1, t.v2.data(), t.v2.size()));
            });

            // outside, same
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(s2.replace(0, 2, t.v2.substr(0, 2)) == 
                           s1.replace(0, 2, t.v2.data(), 2));
            });

            // replace tests for full coverage

            // inside, no effect
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(s2.replace(0, 4, s2.subview(0, 4)) == 
                           s1.replace(0, 4, s1.data() + 0, 4));
            });

            // inside, shrink, split
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(s2.replace(1, 4, s2.subview(4, 2)) == 
                           s1.replace(1, 4, s1.data() + 4, 2));
            });

            // inside, grow no reallocate, split
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(s2.replace(1, 1, s2.subview(0)) == 
                           s1.replace(1, 1, s1.data(), s1.size()));
            });

            // inside, reallocate, split
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                s1.append(s1);
                s2.append(s2);
                BOOST_TEST(s2.replace(1, 1, s2.subview(0)) == 
                           s1.replace(1, 1, s1.data(), s1.size()));
            });

            // inside, same, split
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(s2.replace(1, 2, s2.subview(0, 2)) == 
                           s1.replace(1, 2, s1.data(), 2));
            });
        }

        // replace(const_iterator, const_iterator, string_view)
        {
            // outside, shrink
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(
                  s2.replace(
                      s2.begin(), 
                      s2.begin() + 4,
                      t.v2.substr(4, 2)) == 
                  s1.replace(0, 
                      4, t.v2.data() + 4, 
                      2));
            });

            // outside, grow
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(
                    s2.replace(
                        s2.begin(), 
                        s2.begin() + 1, 
                        t.v2.substr(0)) == 
                    s1.replace(0, 
                        1, t.v2.data(), 
                        t.v2.size()));
            });

            // outside, same
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(
                    s2.replace(
                        s2.begin(), 
                        s2.begin() + 2, 
                        t.v2.substr(0, 2)) == 
                    s1.replace(
                        0, 2, 
                        t.v2.data(), 
                        2));
            });

            // inside, shrink
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(
                    s2.replace(
                        s2.begin() + 1,
                        s2.begin() + 5,
                        s2.subview(4, 2)) ==
                    s1.replace(
                        1, 4,
                        s1.data() + 4,
                        2));
            });

            // inside, grow
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(
                    s2.replace(
                        s2.begin() + 1, 
                        s2.begin() + 2, 
                        s2.subview(0)) == 
                    s1.replace(
                        1, 1, 
                        s1.data(),
                        s1.size()));
            });

            // inside, same
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(
                    s2.replace(
                        s2.begin() + 1, 
                        s2.begin() + 3, 
                        s2.subview(0, 2)) == 
                    s1.replace(
                        1, 2, 
                        s1.data(), 
                        2));
            });
        }

        // replace(std::size_t, std::size_t, std::size_t, char)
        {
            // grow, no realloc
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(s2.replace(0, 4, 10, 'a') == 
                           s1.replace(0, 4, 10, 'a'));
            });

            // grow, realloc
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                const auto grow = (std::max)(s1.capacity(), s2.capacity());
                BOOST_TEST(s2.replace(0, 4, grow, 'a') ==
                           s1.replace(0, 4, grow, 'a'));
            });

            // no change in size
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(s2.replace(0, 1, 1, 'a') ==
                           s1.replace(0, 1, 1, 'a'));
            });

            // pos out of range
            fail_loop([&](storage_ptr const& sp)
            {
                string s(t.v2, sp);
                BOOST_TEST_THROWS(s.replace(s.size() + 1, 1, 1, 'a'), 
                    std::out_of_range);
            });
        }

        // replace(const_iterator, const_iterator, std::size_t, char)
        {
            fail_loop([&](storage_ptr const& sp)
            {
                std::string s1(t.v2.data(), t.v2.size());
                string s2(t.v2, sp);
                BOOST_TEST(
                  s2.replace(s2.begin(), s2.begin() + 4, 10, 'a') ==
                  s1.replace(0, 4, 10, 'a'));
            });
        }
    }

    void
    testSubStr()
    {
        test_vectors const t;
        string const s1 = t.v1;
        string const s2 = t.v2;

        // subview(size_type, size_type)
        BOOST_TEST(s1.subview() == t.v1);
        BOOST_TEST(s1.subview(1) == t.v1.substr(1));
        BOOST_TEST(s1.subview(1, 3) == t.v1.substr(1, 3));
        BOOST_TEST(s2.subview() == t.v2);
        BOOST_TEST(s2.subview(1) == t.v2.substr(1));
        BOOST_TEST(s2.subview(1, 3) == t.v2.substr(1, 3));
    }

    void
    testCopy()
    {
        test_vectors const t;

        // copy(char*, count, pos)
        {
            {
                string s(t.v1);
                std::string d;
                d.resize(s.size());
                s.copy(&d[0], d.size(), 0);
                BOOST_TEST(d == t.v1);
            }

            {
                string s(t.v1);
                std::string d;
                d.resize(s.size());
                s.copy(&d[0], d.size());
                BOOST_TEST(d == t.v1);
            }
        }
    }

    void
    testResize()
    {
        test_vectors const t;

        // resize(size_type)
        {
            fail_loop([&](storage_ptr const& sp)
            {
                string s(sp);
                s.resize(t.v1.size());
                BOOST_TEST(s.size() == t.v1.size());
                BOOST_TEST(s == string(t.v1.size(), '\0'));
            });

            fail_loop([&](storage_ptr const& sp)
            {
                string s(sp);
                s.resize(t.v2.size());
                BOOST_TEST(s.size() == t.v2.size());
                BOOST_TEST(s == string(t.v2.size(), '\0'));
            });

            fail_loop([&](storage_ptr const& sp)
            {
                string s(sp);
                s.resize(t.v1.size());
                s.resize(t.v2.size());
                BOOST_TEST(s == string(t.v2.size(), '\0'));
                s.resize(t.v1.size());
                BOOST_TEST(s == string(t.v1.size(), '\0'));
            });
        }

        // resize(size_type, char)
        {
            fail_loop([&](storage_ptr const& sp)
            {
                string s(sp);
                s.resize(t.v1.size(), '*');
                BOOST_TEST(s.size() == t.v1.size());
                BOOST_TEST(s == string(t.v1.size(), '*'));
            });

            fail_loop([&](storage_ptr const& sp)
            {
                string s(sp);
                s.resize(t.v2.size(), '*');
                BOOST_TEST(s.size() == t.v2.size());
                BOOST_TEST(s == string(t.v2.size(), '*'));
            });

            fail_loop([&](storage_ptr const& sp)
            {
                string s(sp);
                s.resize(t.v1.size(), '*');
                s.resize(t.v2.size(), '*');
                BOOST_TEST(s == string(t.v2.size(), '*'));
                s.resize(t.v1.size());
                BOOST_TEST(s == string(t.v1.size(), '*'));
            });
        }
    }

    void
    testSwap()
    {
        test_vectors const t;

        // swap
        {
            fail_loop([&](storage_ptr const& sp)
            {
                string s1(t.v1, sp);
                string s2(t.v2, sp);
                s1.swap(s2);
                BOOST_TEST(s1 == t.v2);
                BOOST_TEST(s2 == t.v1);
            });

            fail_loop([&](storage_ptr const& sp)
            {
                string s1(t.v1, sp);
                string s2(t.v2, sp);
                swap(s1, s2);
                BOOST_TEST(s1 == t.v2);
                BOOST_TEST(s2 == t.v1);
            });

            fail_loop([&](storage_ptr const& sp)
            {
                string s1(t.v1);
                string s2(t.v2, sp);
                s1.swap(s2);
                BOOST_TEST(s1 == t.v2);
                BOOST_TEST(s2 == t.v1);
            });
        }
    }

    void
    testFind()
    {
        test_vectors const t;
        string const s1 = t.v1;

        // find(string_view, size_type)
        BOOST_TEST(s1.find("bcd") == 1);
        BOOST_TEST(s1.find("cde") == 2);

        BOOST_TEST(s1.find("bcd", 0) == 1);
        BOOST_TEST(s1.find("cde", 1) == 2);
        BOOST_TEST(s1.find("efg", 5) == string::npos);

        // find(char, size_type)
        BOOST_TEST(s1.find('b') == 1);
        BOOST_TEST(s1.find('c', 1) == 2);
        BOOST_TEST(s1.find('e', 5) == string::npos);
    }

