    testHash()
    {
        // libstdc++ 4.8 bug
#if !defined(__GNUC__) || (__GNUC__ > 4 || \
    (__GNUC__ == 4 && __GNUC_MINOR__ > 8))
        {
            std::unordered_set<string> us;
            us.emplace("first");
            us.emplace("second");
        }
        {
            std::unordered_set<string>(
                0,
                std::hash<string>(32));
        }
#endif
        {
            std::hash<string> h1(32);
            std::hash<string> h2(h1);
            std::hash<string> h3(59);
            h1 = h3;
            h2 = h3;
