    QObject::connect(ce, SIGNAL(inFocus(bool)), this, SLOT(m_inFocus(bool)));

    //QObject::connect(this, SIGNAL(inFocus(bool)), cs, SIGNAL(inFocus(bool)));
    //QObject::connect(this, SIGNAL(inFocus(bool)), ce, SIGNAL(inFocus(bool)));

    this->show();
