template <class V, std::enable_if_t<std::is_unsigned_v<V>, int> = 0>
[[nodiscard]] constexpr V bit_width( const V value ) noexcept
{
    V result = 0u;
    V temp = value;
    while( temp != 0u )
    {
        ++result;
        temp >>= static_cast<V>( 1u );
    }
    return result;
}

