uint8_t MmeCommonUtils::select_preferred_int_algo(uint8_t &val)
{
	uint8_t result = 0;

	for(int i = 0; i < MAX_ALGO_COUNT; i++)
    {
        if (val & (0x80 >> mme_cfg->integrity_alg_order[i]))
        {
            result = mme_cfg->integrity_alg_order[i];
            break;
        }
    }

	return result;
}

