{
    return new TypeSceneItem( *this, record, x, y, z );
}

QList<TypeSceneItem*> TypeScene::FromRecord( TypeRecord& record ) const
{
    QList<TypeSceneItem*> result;

    for( TypeSceneItem* item : Items() )
    {
        if( & item->Record() == & record )
            result.append( item );
    }

    return result;
}

