SATSolver::SATSolver(SATInstance* pSATInstance_, ostream& xOutputStream_)
: xOutputStream(xOutputStream_),
  _pPrimaryVariables(0)
{
  _pInstance = pSATInstance_;
  _aAssignment = 0;

  // Set intelligent defaults for runtime parameters:
  _bFindAll = 1; // default to finding one solution
  _iMaxSolutions = 1;
  _fFudgeFactor = .9;
  _iLearnOrder = 3;
  _bNoTimeLimit = 0;
  _iMaxTime = 43200; // 12 hours
  _bFavorSmallClauses = 1;
  _bRelevanceBounding = 1;
  _bPrintStack = 1;
  _iPrintStackPeriod = 10;
  _bRestarts = 0;
  _iRestartIncrement = 0;
}

SATSolver::~SATSolver()
{
  _xLearnedClauses.vDestroy();
  delete _pPrimaryVariables;
}

relsat_enum SATSolver::eSolve()
{
  time(&_iElapsedTime);
  _iLastCheckTime = _iElapsedTime;
  relsat_enum eReturn;
  _iBranchSelections = _iVariablesLabeled = _iContradictions = 0;
  if (!_bInitialize()) {
    eReturn = UNSAT;
  }
  else {
    // Here we do an initial unit propagation to handle base unit clauses.
    if (_bUnitPropagate()) {
      eReturn = UNSAT;
    }
    else {
      boolean bFailed_;
      boolean bReturn;
      if (_bRestarts) {
	bReturn = _bRestartLoop(bFailed_);
      }
      else {
	bReturn = _bLoop(bFailed_);
      }
      if (bFailed_) {
	eReturn = TIMEOUT;
	xOutputStream << "c   Timeout." << endl;
      }
      else if (bReturn == 1) {
	eReturn = SAT;
      }
      else {
	eReturn = UNSAT;
      }
    }
  }
  _vCleanup();
  time_t iEnd;
  time(&iEnd);
  _iElapsedTime = iEnd - _iElapsedTime;
  return eReturn;
}

void SATSolver::vSetPrintStackPeriod(long int iSeconds_)
{
  _iPrintStackPeriod = iSeconds_;
  _bPrintStack = 1;
}

void SATSolver::vSetRestartInterval(int iSeconds_)
{
  _iRestartInterval = iSeconds_;
  _bRestarts = 1;
}

void SATSolver::vSetRestartIncrement(int iSeconds_)
{
  _iRestartIncrement = iSeconds_;
}

void SATSolver::vOutputStatusUpdateInterval()
{
  if (_bPrintStack) {
    xOutputStream << "c Status update interval: " << _iPrintStackPeriod << " seconds." << endl;
  }
}

void SATSolver::vOutputWarnings()
{
  xOutputStream << "c Learn order: " << _iLearnOrder << endl;
  xOutputStream << "c Fudge factor: " << _fFudgeFactor << endl;
  if (!_bNoTimeLimit) {
    xOutputStream << "c Solution phase timeout after: " << _iMaxTime << " seconds." << endl;
  }
  if (_bRestarts) {
    xOutputStream << "c Restart interval: " << _iRestartInterval << " seconds." << endl;
    if (_iRestartIncrement) {
      xOutputStream << "c Restart interval increment: " << _iRestartIncrement << " seconds." << endl;
    }
    if (!_bFindAll) {
      xOutputStream << "c WARNING: Restarts override model counting. Searching for first solution only."
	   << endl;
      _bFindAll = 1;
      _iMaxSolutions = 1;
    }
    else {
      if (_iMaxSolutions == 0) {
	xOutputStream << "c WARNING: Find all solutions not a valid option when using restarts.\n"
	     << "c          Searching for first solution only." << endl;
	_iMaxSolutions = 1;
      }
    }
    xOutputStream << "c Finding up to " << _iMaxSolutions << " solutions with restarts." << endl;
    if (_iMaxSolutions > 1) {
      xOutputStream <<"c WARNING: With restarts, some solutions may be duplicates." << endl;
    }
  }
  else {
    if (!_bFindAll) {
      xOutputStream << "c Counting solutions (will output first solution if one exists)..." << endl;
#ifdef NO_GMP
      xOutputStream << "c WARNING: Not using a bignum package. Solution counts may overflow." << endl;
#endif
    }
    else {
      if (_iMaxSolutions == 0) {
	xOutputStream << "c Finding all solutions..." << endl;
      }
      else {
	xOutputStream << "c Finding up to " << _iMaxSolutions << " solutions..." << endl;
      }
    }
  }
}

