void Hyperion::startTimer(long timeout) {
    _timerRunning++;
    static Poco::TimerCallback<Hyperion> timerCallback(*this, &Hyperion::onTimer);
    _timer.setStartInterval(timeout);
    _timer.start(timerCallback);
}

void Hyperion::stopTimer() {
    _timerRunning--;
    _timer.stop();
    update();
}

void Hyperion::update() {
    static Poco::FastMutex mutex;

    if (!mutex.tryLock()) {
        return;
    }

    // Update the muxer, cleaning obsolete priorities
    int64_t now = Poco::Timestamp().epochMicroseconds() / 1000;
    _muxer.setCurrentTime(now);

    // Obtain the current priority channel
    int priority = _muxer.getCurrentPriority();
    PriorityMuxer::InputInfo priorityInfo = _muxer.getInputInfo(priority);
    long timeout_ms = priorityInfo.timeoutTime_ms > 0 ? (priorityInfo.timeoutTime_ms - now) : 0;
    //std::cout << "update() current priorityInfo: " << priorityInfo << " - TO: " << timeout_ms << std::endl;

    // Apply the transform to each led and color-channel
    std::vector<ColorRgb> ledColors = _raw2ledTransform->applyTransform(priorityInfo.ledColors);
    const std::vector<Led> &leds = _ledString.leds();
    unsigned long i = 0;
    for (ColorRgb &color : ledColors) {
        const ColorOrder ledColorOrder = leds.at(i).colorOrder;
        // correct the color byte order
        switch (ledColorOrder) {
            case ORDER_RGB:
                // leave as it is
                break;
            case ORDER_BGR:
                std::swap(color.red, color.blue);
                break;
            case ORDER_RBG:
                std::swap(color.green, color.blue);
                break;
            case ORDER_GRB:
                std::swap(color.red, color.green);
                break;
            case ORDER_GBR: {
                uint8_t temp = color.red;
                color.red = color.green;
                color.green = color.blue;
                color.blue = temp;
                break;
            }
            case ORDER_BRG: {
                uint8_t temp = color.red;
                color.red = color.blue;
                color.blue = color.green;
                color.green = temp;
                break;
            }
        }
        i++;
    }

    // Write the data to the device
    _device->write(ledColors);

    // Start the timeout-timer
    if (timeout_ms > 0) {
        if (_timerRunning == 0) {
            startTimer(timeout_ms);
        }
    } else if (_timerRunning > 0) {
        stopTimer();
    }

    mutex.unlock();
}

void Hyperion::onTimer(Poco::Timer &timer) {
    stopTimerEvent.notifyAsync(nullptr);
}

/*
 * sortProcess.cpp :
 * Changes all sortindexes in the file to the given index.
 */

#include <iostream>
#include <string>
#include <vector>

#include "../../CatOfEvilGenius/library/DBPF.h"
#include "../../CatOfEvilGenius/library/DBPF_types.h"
#include "../../CatOfEvilGenius/library/DBPF_BINX.h"

using namespace std;

extern "C" // for exporting to shared library for use in Python
bool sortProcess(const char* filename, const int index) {
  // extra crunchy goodness for restoring state after outputting in hex format
  // ios_base::fmtflags f(cout.flags());
  // clog << endl << "Sorting " << filename << " into index " << hex << index << "..." << endl;
  // cout.flags(f);

  DBPFtype package;
  vector<DBPF_resourceType*> resources;

  // Types that should be decompressed and loaded when opening the file.
  vector<unsigned int> typesToInit;
  typesToInit.push_back(DBPF_BINX);

  // Open package file and read/populate chosen (typesToInit) resources.
  if(!readPackage(filename, package, typesToInit, resources)) {
    cerr << "Opening and reading from " << filename << " failed. Sorting aborted." << endl;
    return false;
  }

  // Set all sortindices
  int item_count = resources.size();
  DBPF_resourceType* pResource = NULL;

  for (int i = 0; i < item_count; i++) {
    pResource = resources[i];

    if (NULL == pResource) {
      continue;
    }

    if (DBPF_BINX == pResource->getType()) {
      if (((DBPF_BINXtype*)pResource)->setSortIndex(index)) {
        // clog << "\t" << "Set BINX resource " << i << "." << endl;
      }
    }
  }

  // clog << "Sorting complete!" << endl;

  // Write back to file
  // clog << endl << "Overwriting file " << filename << "..." << endl;
  bool write_success = writeCompressedPackage(filename, package, resources);
  if (!write_success) {
    cerr << "Writing to file " << filename << " failed. File may be corrupted... " <<
            "or you may have the file open somewhere else (SimPE, maybe?). " <<
            "If so, close the file elsewhere and try again." << endl;
  }
  // else {
  //   clog << "File written!" << endl;
  // }

  // Clean up
  if (!resources.empty()) {
    size_t vec_size = resources.size();
    for (size_t i = 0; i < vec_size; i++) {
      if (resources[i] != NULL) {
        delete resources[i];
        resources[i] = NULL;
      }
      resources.clear();
    }
  }

  return write_success;
}

