template <typename T>
class ScopedFlagSetter {
 public:
  ScopedFlagSetter(absl::Flag<T>* flag, const T& value)
      : flag_(flag), original_value_(absl::GetFlag(*flag)) {
    absl::SetFlag(flag, value);
  }

  ~ScopedFlagSetter() { absl::SetFlag(flag_, original_value_); }

 private:
  absl::Flag<T>* flag_;
  T original_value_;
};

