void QSDebugClass::dumpScope( QSEnv * env )
{
    ScopeChain chain = env->scope();
    ScopeChain::ConstIterator it = chain.begin();
    qDebug( "\n---------- DUMP SCOPE ----------" );
    while( it!=chain.end() ) {
	qs_dumpobject( *it );
	if( (*it).objectType() == env->typeClass() ) {
            QSList itList( *it );
	    qs_dumptype( itList );
	}
	it++;
    }
    qDebug( "---------- DUMP COMPLETE ----------" );
}


