#include "particle.h"
#include "particleaffector.h"
#include <framework/core/clock.h>

ParticleAffector::ParticleAffector()
{
    m_active = false;
    m_finished = false;
    m_delay = 0;
    m_duration = 0;
    m_elapsedTime = 0;
}

void ParticleAffector::update(float elapsedTime)
{
    if(m_duration >= 0 && m_elapsedTime >= m_duration + m_delay) {
        m_finished = true;
        return;
    }

    if(!m_active && m_elapsedTime > m_delay)
        m_active = true;

    m_elapsedTime += elapsedTime;
}

bool ParticleAffector::load(const OTMLNodePtr& node)
{
    float minDelay = 0, maxDelay = 0;
    float minDuration = -1, maxDuration = -1;

    for(const OTMLNodePtr& childNode : node->children()) {
        if(childNode->tag() == "delay") {
            minDelay = childNode->value<float>();
            maxDelay = childNode->value<float>();
        }
        else if(childNode->tag() == "min-delay")
            minDelay = childNode->value<float>();
        else if(childNode->tag() == "max-delay")
            maxDelay = childNode->value<float>();

        if(childNode->tag() == "duration") {
            minDuration = childNode->value<float>();
            maxDuration = childNode->value<float>();
        }
        else if(childNode->tag() == "min-duration")
            minDuration = childNode->value<float>();
        else if(childNode->tag() == "max-duration")
            maxDuration = childNode->value<float>();
    }

    m_delay = Fw::randomRange(minDelay, maxDelay);
    m_duration = Fw::randomRange(minDuration, maxDuration);

    return true;
}

bool GravityAffector::load(const OTMLNodePtr& node)
{
    if(!ParticleAffector::load(node))
        return false;

    m_angle = 270 * DEG_TO_RAD;
    m_gravity = 9.8;

    for(const OTMLNodePtr& childNode : node->children()) {
        if(childNode->tag() == "angle")
            m_angle = childNode->value<float>() * DEG_TO_RAD;
        else if(childNode->tag() == "gravity")
            m_gravity = childNode->value<float>();
    }
    return true;
}

void GravityAffector::updateParticle(const ParticlePtr& particle, float elapsedTime)
{
    if(!m_active)
        return;

    PointF velocity = particle->getVelocity();
    velocity += PointF(m_gravity * elapsedTime * cos(m_angle), m_gravity * elapsedTime * sin(m_angle));
    particle->setVelocity(velocity);
}

bool AttractionAffector::load(const OTMLNodePtr& node)
{
    if(!ParticleAffector::load(node))
        return false;

    m_acceleration = 32;
    m_reduction = 0;
    m_repelish = false;

    for(const OTMLNodePtr& childNode : node->children()) {
        if(childNode->tag() == "position")
            m_position = childNode->value<Point>();
        else if(childNode->tag() == "acceleration")
            m_acceleration = childNode->value<float>();
        else if(childNode->tag() == "velocity-reduction-percent")
            m_reduction = childNode->value<float>();
        else if(childNode->tag() == "repelish")
            m_repelish = childNode->value<bool>();
    }
    return true;
}

void AttractionAffector::updateParticle(const ParticlePtr& particle, float elapsedTime)
{
    if(!m_active)
        return;

    PointF pPosition = particle->getPosition();
    PointF d = PointF(m_position.x - pPosition.x, pPosition.y - m_position.y);
    if(d.length() == 0)
        return;

    PointF direction = PointF(1, 1);
    if(m_repelish)
        direction = PointF(-1, -1);

    PointF pVelocity = particle->getVelocity() + (d / d.length() * m_acceleration * elapsedTime) * direction;
    particle->setVelocity(pVelocity - pVelocity * m_reduction/100.0 * elapsedTime);
}

#include <iostream>
#include <fstream>
#include <cstring>
#include <glad/glad.h>
#include "debug.h"
#include "model.h"


Model::Model(const char *vertexShaderSourcePath, const char *fragmentShaderSourcePath) {
    char vPath[128] = "\0", fPath[128] = "\0";
    fullPath(vertexShaderSourcePath, vPath);
    fullPath(fragmentShaderSourcePath, fPath);

    char vSource[10240] = "\0", fSource[10240] = "\0";
    loadSource(vPath, vSource);
    loadSource(fPath, fSource);
    compileVertexShader(vSource);
    compileFragmentShader(fSource);
    compileLinkProgram();
}

Model::~Model() {
    // delete all?
    glDeleteShader(vertexShader);
    glDeleteShader(fragmentShader);
    glDeleteVertexArrays(1, &VAO);
    glDeleteBuffers(1, &VBO);
    glDeleteProgram(program);
}

void Model::render() {
    glUseProgram(program);
    glBindVertexArray(VAO);
    glDrawArrays(GL_TRIANGLES, 0, 3);
}

void Model::toX(float *vertices, unsigned int size) {
    createVBO(vertices, size);
}

void Model::fullPath(const char *path, char *full) {
    strcat(full, __DIR__); //@TODO
    strcat(full, path);
    strcat(full, ".txt");

    DEBUG("MODEL::FULLPATH", full, DEBUG_L::INFO);
}

void Model::loadSource(const char *path, char *source) {
    std::ifstream file(path);
    if (!file) {
        DEBUG("MODEL::LOADSOURCE", "failed open file", DEBUG_L::ERROR);
        return; 
    }

    // get length of file
    file.seekg(0, file.end);
    int length = file.tellg();
    file.seekg(0, file.beg);

    // if length > 10k, throw ERROR
    if (length > 10240) {
        DEBUG("MODEL::LOADSOURCE ", "length must < 1KB", DEBUG_L::ERROR);
        return;
    }

    // @TODO
    file.read(source, length);

    DEBUG("MODEL::LOADSOURCE", source, DEBUG_L::INFO);
    file.close();
}

unsigned int Model::getShaderWithSource(const char *source, unsigned int type) {
    if (!source) return -1;
    //@TODO type check

    int  result = 0;
    char message[512];
    unsigned int shader;

    shader = glCreateShader(type);
    glShaderSource(shader, 1, &source, NULL);
    glCompileShader(shader);

    glGetShaderiv(shader, GL_COMPILE_STATUS, &result);

    if (!result) {
        glGetShaderInfoLog(shader, 512, NULL, message);
        // @TODO
        DEBUG("MODEL::COMPILE", message, DEBUG_L::ERROR);
    }

    return shader;
}

void Model::compileVertexShader(const char *source) {
    vertexShader = getShaderWithSource(source, GL_VERTEX_SHADER);
}

void Model::compileFragmentShader(const char *source) {
    fragmentShader = getShaderWithSource(source, GL_FRAGMENT_SHADER);
}

void Model::compileLinkProgram() {

    int result = 0;
    char message[512];

    program = glCreateProgram();
    glAttachShader(program, vertexShader);
    glAttachShader(program, fragmentShader);
    glLinkProgram(program);
    glGetProgramiv(program, GL_LINK_STATUS, &result);
    if (!result) {
        glGetProgramInfoLog(program, 512, NULL, message);
        DEBUG("MODEL::COMPILELINKPROGRAM", message, DEBUG_L::ERROR);
    }
    //@TODO link error
}

void Model::createVBO(float *vertices, unsigned int size) {
    glGenVertexArrays(1, &VAO);
    glGenBuffers(1, &VBO);

    glBindVertexArray(VAO);
    glBindBuffer(GL_ARRAY_BUFFER, VBO);
    glBufferData(GL_ARRAY_BUFFER, size, vertices, GL_STATIC_DRAW);

    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 3 * sizeof(float), (void *) 0);
    glEnableVertexAttribArray(0);

    glBindBuffer(GL_ARRAY_BUFFER, 0);
    glBindVertexArray(0);
}

