void init() {
	// 未清 0
	// start.clear();
	// dest.clear();
	fill(G[0], G[0] + MAX_L * MAX_L, INF);
	fill(dis[0], dis[0] + MAX_L * MAX_L, INF);
	for (int i = 0; i < MAX_L; i++) {
		G[i][i] = 0;
		dis[i][i] = 0;
	}
}

void floyd() {
	for (int k = 0; k < n; k++) {
		for (int i = 0; i < n; i++) {
			if (G[k][i] == INF) {
				continue;
			}
			for (int j = 0; j < n; j++) {
				dis[i][j] = min(dis[i][k] + dis[k][j], dis[i][j]);
			}
		}
	}
}

