			cin >> a >> b >> c;
			a--;
			b--;
			if (c < G[a][b]) {
				G[a][b] = G[b][a] = dis[a][b] = dis[b][a] = c;
			}
			n = max(n, max(a, b));
		}
		LL temp;
		for (int i = 0; i < s;i++){
			cin >> temp;
			start[i] = temp - 1;
		}
		for (int i = 0; i < d; i++) {
			cin >> temp;
			dest[i] = temp - 1;
		}
