    {
        return (entityWithFocusPtrOpt_ && (entityWithFocusPtrOpt_.value()->KeyPress(KE)));
    }

    bool StageBase::KeyRelease(const sf::Event::KeyEvent & KE)
    {
        return (entityWithFocusPtrOpt_ && (entityWithFocusPtrOpt_.value()->KeyRelease(KE)));
